export type EditorKey=keyof typeof words;
export function editorDictionary(lang:Language):Record<EditorKey,string>{const index=({de:0,en:1,es:2,fr:3})[lang];return Object.fromEntries(Object.entries(words).map(([k,v])=>[k,v[index]])) as Record<EditorKey,string>;}
